function foodCategories(){return `<div class="category-chips" role="group" aria-label="Категории еды">${['Все категории',...demoFoodGroups.map(g=>g[0]),'Свои'].map(category=>`<button class="category-chip" data-action="food-category" data-value="${category}" aria-pressed="${(state.foodCategory||'Все категории')===category}">${esc(category)}</button>`).join('')}</div>`;}
function foodCategoryAction(a,b){
 if(a==='food-category'){state.foodCategory=b.dataset.value;state.catalogLimit=12;render();return true;}
 if(a==='catalog-more'){state.catalogLimit=(state.catalogLimit||12)+12;document.getElementById('results').innerHTML=catalogResults();return true;}
 return false;
}
